import { MakeLogicType, actions, connect, kea, listeners, path, reducers } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import type { ModeValue } from 'scenes/max/components/ModeSelector'
import { maxContextLogic } from 'scenes/max/maxContextLogic'
import { stashPendingMaxContext } from 'scenes/max/maxLogic'
import type { MaxUIContext } from 'scenes/max/maxTypes'
import { urls } from 'scenes/urls'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeClassicComposerLogicValues {
    compiledContext: MaxUIContext | null // maxContextLogic
    mode: ModeValue
    prompt: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeClassicComposerLogicActions {
    chatStarted: (prompt: string) => {
        prompt: string
    }
    setMode: (mode: ModeValue) => {
        mode: ModeValue
    }
    setPrompt: (prompt: string) => {
        prompt: string
    }
}

export type todayHomeClassicComposerLogicType = MakeLogicType<
    todayHomeClassicComposerLogicValues,
    todayHomeClassicComposerLogicActions
>

/**
 * The home composer for people without PostHog AI 2.0. It holds the draft, the mode and the picked context
 * until the person sends, and then gives all three to the PostHog AI chat.
 */
export const todayHomeClassicComposerLogic = kea<todayHomeClassicComposerLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayHomeClassicComposerLogic']),
    connect(() => ({
        values: [maxContextLogic, ['compiledContext']],
    })),
    actions({
        setPrompt: (prompt: string) => ({ prompt }),
        setMode: (mode: ModeValue) => ({ mode }),
        chatStarted: (prompt: string) => ({ prompt }),
    }),
    reducers({
        prompt: [
            '',
            {
                setPrompt: (_, { prompt }) => prompt,
                chatStarted: () => '',
            },
        ],
        mode: [null as ModeValue, { setMode: (_, { mode }) => mode }],
    }),
    listeners(({ values }) => ({
        chatStarted: ({ prompt }) => {
            posthog.capture('today home chat started', {
                agent_mode: values.mode,
                has_context: !!values.compiledContext,
            })
            // The chat reads this once and then deletes it. maxContextLogic clears the picked context when the
            // route changes, so it must be stored before the navigation.
            if (values.compiledContext) {
                stashPendingMaxContext(values.compiledContext)
            }
            router.actions.push(urls.ai(undefined, prompt.trim(), values.mode ?? undefined))
        },
    })),
])
